package com.sobrenaturaldirector.spatial.geometry;

public final class LocalAabb {private final LocalVec3i min,max;public LocalAabb(LocalVec3i min,LocalVec3i max){if(min==null||max==null||max.getX()<=min.getX()||max.getY()<=min.getY()||max.getZ()<=min.getZ())throw new IllegalArgumentException("positive local AABB required");this.min=min;this.max=max;}public static LocalAabb sized(LocalVec3i origin,int width,int height,int depth){if(width<=0||height<=0||depth<=0)throw new IllegalArgumentException("positive dimensions required");return new LocalAabb(origin,origin.add(width,height,depth));}public LocalVec3i getMin(){return min;}public LocalVec3i getMax(){return max;}public int getWidth(){return max.getX()-min.getX();}public int getHeight(){return max.getY()-min.getY();}public int getDepth(){return max.getZ()-min.getZ();}public long volume(){return Math.multiplyExact(Math.multiplyExact((long)getWidth(),getHeight()),getDepth());}public boolean contains(LocalVec3i p){return p.getX()>=min.getX()&&p.getX()<max.getX()&&p.getY()>=min.getY()&&p.getY()<max.getY()&&p.getZ()>=min.getZ()&&p.getZ()<max.getZ();}public boolean contains(LocalAabb b){return contains(b.min)&&b.max.getX()<=max.getX()&&b.max.getY()<=max.getY()&&b.max.getZ()<=max.getZ();}public boolean overlaps(LocalAabb b){return min.getX()<b.max.getX()&&max.getX()>b.min.getX()&&min.getY()<b.max.getY()&&max.getY()>b.min.getY()&&min.getZ()<b.max.getZ()&&max.getZ()>b.min.getZ();}public LocalAabb union(LocalAabb b){return new LocalAabb(new LocalVec3i(Math.min(min.getX(),b.min.getX()),Math.min(min.getY(),b.min.getY()),Math.min(min.getZ(),b.min.getZ())),new LocalVec3i(Math.max(max.getX(),b.max.getX()),Math.max(max.getY(),b.max.getY()),Math.max(max.getZ(),b.max.getZ())));}}
